<!--
 * 消息偏好设置表单组件
 *
 * @path apps/message-web/src/views/preference/preference-form.vue
 * @author ydsz-team
 * @since 1.0.0
 * @modified 4.1.0 由脚手架 CRUD 重写为契约 API：偏好配置表单（PreferenceUpsertDTO）提交 upsert()。
-->
<script lang="ts" setup>
import { $t } from '@ydsz/locales';
/**
 * 消息偏好（表单组件）
 * <p>消费后端契约 PreferenceController#upsert（src/api/preference.ts，auto-generated by bash/gen-contract.py）：
 * 按 PreferenceUpsertDTO 字段（userId/channel/bizType/enabled/dndEnabled/dndStart/dndEnd/dailyLimit/
 * hourlyLimit/digestEnabled/digestFrequency/locale 等）填写，编辑时回填 MsgPreferenceVO 字段，
 * 提交统一调 upsert(data)（契约仅提供 upsert，无独立 create/update），成功后 emit('success') 并关闭弹窗。
 *
 * @author ydsz-team
 * @since 1.0.0
 */
import { useYdModal } from '@ydsz/common-ui';
import {
  YdForm,
  YdFormItem,
  YdNumberFieldInput,
  YdInput,
  YdRadioGroup,
  YdRadioGroupItem,
  YdSelectBase,
  YdSelectContentBase,
  YdSelectItemBase,
  YdSelectTriggerBase,
  YdSelectValueBase,
  YdTextarea,
} from '@ydsz-core/ydsz-ui';
import { computed, reactive, ref } from 'vue';

import { showToast } from '@ydsz/notification';

import { upsert } from '#/api/preference';
import type { MsgPreferenceVO } from '#/api/models';

const emit = defineEmits<{ success: [] }>();

const formRef = ref();
const isEdit = ref(false);

/** 偏好表单状态（字段对应 PreferenceUpsertDTO，enabled 等以 0/1 表示） */
interface PreferenceFormState {
  userId: string;
  channel: string;
  bizType: string;
  enabled: number;
  dndEnabled: number;
  dndStart: string;
  dndEnd: string;
  dailyLimit: number;
  hourlyLimit: number;
  digestEnabled: number;
  digestFrequency: string;
  locale: string;
}

const formData = reactive<PreferenceFormState>({
  userId: 'current',
  channel: '',
  bizType: '',
  enabled: 1,
  dndEnabled: 0,
  dndStart: '',
  dndEnd: '',
  dailyLimit: 0,
  hourlyLimit: 0,
  digestEnabled: 0,
  digestFrequency: '',
  locale: '',
});

const rules = {
  channel: [{ required: true, message: $t('preference.channelRequired'), trigger: 'blur' }],
};

const [Modal, modalApi] = useYdModal({
  onOpenChange: (isOpen: boolean) => {
    if (!isOpen) return;
    const data = modalApi.getData<{ record?: MsgPreferenceVO }>();
    if (data?.record) {
      isEdit.value = true;
      Object.assign(formData, {
        userId: data.record.userId ?? 'current',
        channel: data.record.channel ?? '',
        bizType: data.record.bizType ?? '',
        enabled: data.record.enabled ?? 1,
        dndEnabled: data.record.dndEnabled ?? 0,
        dndStart: data.record.dndStart ?? '',
        dndEnd: data.record.dndEnd ?? '',
        dailyLimit: data.record.dailyLimit ?? 0,
        hourlyLimit: data.record.hourlyLimit ?? 0,
        digestEnabled: data.record.digestEnabled ?? 0,
        digestFrequency: data.record.digestFrequency ?? '',
        locale: data.record.locale ?? '',
      });
    } else {
      isEdit.value = false;
      Object.assign(formData, {
        userId: 'current',
        channel: '',
        bizType: '',
        enabled: 1,
        dndEnabled: 0,
        dndStart: '',
        dndEnd: '',
        dailyLimit: 0,
        hourlyLimit: 0,
        digestEnabled: 0,
        digestFrequency: '',
        locale: '',
      });
    }
  },
  onConfirm: async () => {
    try {
      await formRef.value?.validate();
    } catch {
      return;
    }
    modalApi.lock();
    try {
      await upsert({
        userId: formData.userId || undefined,
        channel: formData.channel,
        bizType: formData.bizType || undefined,
        enabled: formData.enabled,
        dndEnabled: formData.dndEnabled,
        dndStart: formData.dndStart || undefined,
        dndEnd: formData.dndEnd || undefined,
        dailyLimit: formData.dailyLimit,
        hourlyLimit: formData.hourlyLimit,
        digestEnabled: formData.digestEnabled,
        digestFrequency: formData.digestFrequency || undefined,
        locale: formData.locale || undefined,
      });
      showToast.success(isEdit.value ? $t('operation.update.success') : $t('operation.save.success'));
      emit('success');
      modalApi.close();
    } finally {
      modalApi.unlock();
    }
  },
});

const title = computed(() =>
  isEdit.value ? $t('preference.editTitle') : $t('preference.createTitle'),
);
</script>
<template>
  <Modal :title="title">
    <YdForm
      ref="formRef"
      :model="formData"
      :rules="rules"
      label-width="100px"
      label-position="right"
    >
      <YdFormItem :label="$t('preference.userId')" prop="userId">
        <YdInput v-model="formData.userId" :placeholder="$t('preference.userIdPlaceholder')" />
      </YdFormItem>
      <YdFormItem :label="$t('preference.channel')" prop="channel">
        <YdInput
          v-model="formData.channel"
          :placeholder="$t('preference.channelPlaceholder')"
        />
      </YdFormItem>
      <YdFormItem :label="$t('preference.bizType')" prop="bizType">
        <YdInput
          v-model="formData.bizType"
          :placeholder="$t('preference.bizTypePlaceholder')"
        />
      </YdFormItem>
      <YdFormItem :label="$t('preference.enabled')" prop="enabled">
        <YdRadioGroup v-model="formData.enabled">
          <YdRadioGroupItem :value="1">{{ $t('preference.enabledOn') }}</YdRadioGroupItem>
          <YdRadioGroupItem :value="0">{{ $t('preference.enabledOff') }}</YdRadioGroupItem>
        </YdRadioGroup>
      </YdFormItem>
      <YdFormItem :label="$t('preference.dndEnabled')" prop="dndEnabled">
        <YdRadioGroup v-model="formData.dndEnabled">
          <YdRadioGroupItem :value="1">{{ $t('preference.dndOn') }}</YdRadioGroupItem>
          <YdRadioGroupItem :value="0">{{ $t('preference.dndOff') }}</YdRadioGroupItem>
        </YdRadioGroup>
      </YdFormItem>
      <YdFormItem :label="$t('preference.dndStart')" prop="dndStart">
        <YdInput v-model="formData.dndStart" :placeholder="$t('preference.dndStartPlaceholder')" />
      </YdFormItem>
      <YdFormItem :label="$t('preference.dndEnd')" prop="dndEnd">
        <YdInput v-model="formData.dndEnd" :placeholder="$t('preference.dndEndPlaceholder')" />
      </YdFormItem>
      <YdFormItem :label="$t('preference.dailyLimit')" prop="dailyLimit">
        <YdNumberFieldInput v-model="formData.dailyLimit" :min="0" :max="99999" />
      </YdFormItem>
      <YdFormItem :label="$t('preference.hourlyLimit')" prop="hourlyLimit">
        <YdNumberFieldInput v-model="formData.hourlyLimit" :min="0" :max="9999" />
      </YdFormItem>
      <YdFormItem :label="$t('preference.digestEnabled')" prop="digestEnabled">
        <YdRadioGroup v-model="formData.digestEnabled">
          <YdRadioGroupItem :value="1">{{ $t('preference.digestOn') }}</YdRadioGroupItem>
          <YdRadioGroupItem :value="0">{{ $t('preference.digestOff') }}</YdRadioGroupItem>
        </YdRadioGroup>
      </YdFormItem>
      <YdFormItem :label="$t('preference.digestFrequency')" prop="digestFrequency">
        <YdSelectBase v-model="formData.digestFrequency">
          <YdSelectTriggerBase>
            <YdSelectValueBase :placeholder="$t('preference.digestFrequencyPlaceholder')" />
          </YdSelectTriggerBase>
          <YdSelectContentBase>
            <YdSelectItemBase value="DAILY">{{ $t('preference.frequency.daily') }}</YdSelectItemBase>
            <YdSelectItemBase value="WEEKLY">{{ $t('preference.frequency.weekly') }}</YdSelectItemBase>
            <YdSelectItemBase value="MONTHLY">{{ $t('preference.frequency.monthly') }}</YdSelectItemBase>
          </YdSelectContentBase>
        </YdSelectBase>
      </YdFormItem>
      <YdFormItem :label="$t('preference.locale')" prop="locale">
        <YdInput v-model="formData.locale" :placeholder="$t('preference.localePlaceholder')" />
      </YdFormItem>
    </YdForm>
  </Modal>
</template>
